let formSignatures={technician:[],responsible:[]};function resizeCanvas(){const c=$('signCanvas'),rect=c.getBoundingClientRect(),ratio=window.devicePixelRatio||1;c.width=Math.max(1,rect.width*ratio);c.height=Math.max(1,rect.height*ratio);const ctx=c.getContext('2d');ctx.setTransform(ratio,0,0,ratio,0,0);ctx.lineWidth=2.6;ctx.lineCap='round';ctx.lineJoin='round';ctx.strokeStyle='#123f2c'}function drawStrokes(){const c=$('signCanvas'),ctx=c.getContext('2d'),w=c.clientWidth,h=c.clientHeight;ctx.clearRect(0,0,c.width,c.height);for(const stroke of currentStrokes){if(!stroke.length)continue;ctx.beginPath();ctx.moveTo(stroke[0][0]*w,stroke[0][1]*h);for(const p of stroke.slice(1))ctx.lineTo(p[0]*w,p[1]*h);ctx.stroke()}}
function closeSign(){ $('signOverlay').classList.remove('open');$('signOverlay').setAttribute('aria-hidden','true');document.body.style.overflow=''}
const canvas=$('signCanvas');canvas.addEventListener('pointerdown',e=>{activePointer=true;canvas.setPointerCapture(e.pointerId);const r=canvas.getBoundingClientRect();currentStrokes.push([[Math.max(0,Math.min(1,(e.clientX-r.left)/r.width)),Math.max(0,Math.min(1,(e.clientY-r.top)/r.height))]]);drawStrokes()});canvas.addEventListener('pointermove',e=>{if(!activePointer)return;const r=canvas.getBoundingClientRect();currentStrokes.at(-1).push([Math.max(0,Math.min(1,(e.clientX-r.left)/r.width)),Math.max(0,Math.min(1,(e.clientY-r.top)/r.height))]);drawStrokes()});for(const ev of ['pointerup','pointercancel'])canvas.addEventListener(ev,()=>activePointer=false);
$('saveSign').onclick=()=>{if(!currentStrokes.some(s=>s.length>1)){toast('Faça a assinatura na área antes de salvar.');return}formSignatures[signingField]=currentStrokes;const id=signingField==='technician'?'techSignStatus':'personSignStatus';$(id).textContent='Assinatura registrada';$(id).classList.add('done');closeSign()};$('cancelSign').onclick=closeSign;$('clearSign').onclick=()=>{currentStrokes=[];drawStrokes()};window.addEventListener('resize',()=>{if($('signOverlay').classList.contains('open')){resizeCanvas();drawStrokes()}});
$('sector').innerHTML='<option value="">Selecione o setor</option>'+SECTORS.map(s=>`<option>${esc(s)}</option>`).join('');$('month').value=monthNow();stamp();$('sector').onchange=()=>refreshTerm(true);$('equipment').oninput=()=>refreshTerm(true);$('technician').onchange=()=>refreshTerm(true);$('status').onchange=()=>refreshTerm(true);$('justification').oninput=()=>{$('justification').dataset.edited='true'};refreshTerm(true);setInterval(stamp,15000);
